{
  "claims": [
    {
      "beatId": "beat1",
      "source": "narration",
      "text": "In March twenty twenty-five, Larkspur Pay checkout failed for forty-seven minutes.",
      "verdict": "supported",
      "ids": ["fact-18", "num-14"],
      "restates": {
        "claim": "Larkspur Pay checkout failed for forty-seven minutes",
        "fact": "31% of Larkspur Pay checkout requests failed for 47 minutes"
      }
    },
    {
      "beatId": "beat1",
      "source": "narration",
      "text": "Its rate limiter, the gate on every request, let thirty-one percent of them fail.",
      "verdict": "supported",
      "ids": ["fact-18", "num-15"],
      "restates": {
        "claim": "the rate limiter let 31% of checkout requests fail",
        "fact": "the limiter fell back to local limits, the provider throttled all traffic, and 31% of checkout requests failed"
      }
    },
    {
      "beatId": "beat1",
      "source": "value",
      "elementId": "fail-stat",
      "text": "31",
      "label": "Checkouts that failed",
      "verdict": "supported",
      "ids": ["num-15"],
      "restates": {
        "claim": "31% of checkouts failed",
        "fact": "31% share of checkout requests that failed during the incident"
      }
    },
    {
      "beatId": "beat2",
      "source": "narration",
      "text": "Each checkout request gets a key and a token bucket, a pile of passes.",
      "verdict": "supported",
      "ids": ["fact-1", "fact-4"],
      "restates": {
        "claim": "each checkout request gets a key and a token bucket",
        "fact": "a token bucket decides from state kept per key, and the key is built from the API key plus the route group"
      }
    },
    {
      "beatId": "beat2",
      "source": "narration",
      "text": "Say the bucket holds a hundred tokens.",
      "verdict": "supported",
      "ids": ["fact-3", "num-1"],
      "restates": {
        "claim": "the bucket holds a hundred tokens",
        "fact": "a free-tier key gets a capacity of 100 tokens"
      }
    },
    {
      "beatId": "beat2",
      "source": "narration",
      "text": "It refills ten a second; each request spends one.",
      "verdict": "supported",
      "ids": ["fact-2", "fact-3", "num-2"],
      "restates": {
        "claim": "the bucket refills ten tokens a second and each request spends one",
        "fact": "the refill rate is 10 tokens per second and each request takes a token"
      }
    },
    {
      "beatId": "beat2",
      "source": "value",
      "elementId": "bucket",
      "text": "100",
      "label": "capacity",
      "verdict": "supported",
      "ids": ["num-1"],
      "restates": {
        "claim": "the bucket capacity is 100 tokens",
        "fact": "capacity of a free-tier key's bucket is 100 tokens"
      }
    },
    {
      "beatId": "beat2",
      "source": "value",
      "elementId": "bucket",
      "text": "99",
      "label": "capacity",
      "verdict": "issue",
      "ids": []
    },
    {
      "beatId": "beat2",
      "source": "value",
      "elementId": "refill",
      "text": "10",
      "label": "refill rate",
      "verdict": "supported",
      "ids": ["num-2"],
      "restates": {
        "claim": "the refill rate is 10 tokens per second",
        "fact": "refill rate for that key is 10 tokens per second"
      }
    },
    {
      "beatId": "beat3",
      "source": "narration",
      "text": "A shared store fixes this.",
      "verdict": "supported",
      "ids": ["fact-12", "fact-7"],
      "restates": {
        "claim": "a shared store fixes the multiplied limit",
        "fact": "state kept in a shared store makes every instance enforce the same limit, so a client cannot multiply it across nodes"
      }
    },
    {
      "beatId": "beat3",
      "source": "narration",
      "text": "So why not give each gateway node its own bucket?",
      "verdict": "no_claim",
      "ids": []
    },
    {
      "beatId": "beat3",
      "source": "narration",
      "text": "Across, say, twenty-four nodes, a client gets twenty-four times its limit.",
      "verdict": "supported",
      "ids": ["fact-7", "num-3", "num-4"],
      "restates": {
        "claim": "a client spread across 24 nodes gets 24 times its limit",
        "fact": "with a bucket per node, a client spread across all 24 nodes would get 24 times its limit"
      }
    },
    {
      "beatId": "beat3",
      "source": "narration",
      "text": "So one shared store holds the bucket, one place every node reads and writes.",
      "verdict": "supported",
      "ids": ["fact-5", "fact-12"],
      "restates": {
        "claim": "one shared store holds the bucket that every node reads and writes",
        "fact": "the count and timestamp are read and written back to the store, which every instance uses so all enforce the same limit"
      }
    },
    {
      "beatId": "beat3",
      "source": "value",
      "elementId": "gw_nodes",
      "text": "24",
      "label": "title \"24 NODES\"",
      "verdict": "supported",
      "ids": ["num-3"],
      "restates": {
        "claim": "there are 24 gateway nodes",
        "fact": "24 gateway nodes run behind a load balancer"
      }
    },
    {
      "beatId": "beat3",
      "source": "value",
      "elementId": "limit_24",
      "text": "24",
      "label": "times its limit",
      "verdict": "supported",
      "ids": ["num-4", "fact-7"],
      "restates": {
        "claim": "the effective limit becomes 24 times its limit",
        "fact": "a client spread across all 24 nodes would get 24 times its limit"
      }
    },
    {
      "beatId": "beat4",
      "source": "narration",
      "text": "But a shared bucket needs read, refill and write as one step.",
      "verdict": "supported",
      "ids": ["fact-6", "fact-5"],
      "restates": {
        "claim": "read, refill and write must run as one step",
        "fact": "read, compute and write run as one atomic script inside the store"
      }
    },
    {
      "beatId": "beat4",
      "source": "narration",
      "text": "Otherwise two nodes read the same count and both see a token left.",
      "verdict": "supported",
      "ids": ["fact-6"],
      "restates": {
        "claim": "two nodes read the same count and both see a token left",
        "fact": "without atomicity two gateway nodes can read the same count and both see a token left"
      }
    },
    {
      "beatId": "beat4",
      "source": "narration",
      "text": "Both let their request through.",
      "verdict": "supported",
      "ids": ["fact-6"],
      "restates": {
        "claim": "both nodes admit a request",
        "fact": "both gateway nodes let a request through"
      }
    },
    {
      "beatId": "beat4",
      "source": "value",
      "elementId": "node_a",
      "text": "24",
      "label": "one of 24 nodes",
      "verdict": "supported",
      "ids": ["num-3", "fact-7"],
      "restates": {
        "claim": "gateway A is one of 24 nodes",
        "fact": "Hollowmere runs 24 gateway nodes behind a load balancer"
      }
    },
    {
      "beatId": "beat4",
      "source": "value",
      "elementId": "node_b",
      "text": "24",
      "label": "one of 24 nodes",
      "verdict": "supported",
      "ids": ["num-3", "fact-7"],
      "restates": {
        "claim": "gateway B is one of 24 nodes",
        "fact": "Hollowmere runs 24 gateway nodes behind a load balancer"
      }
    },
    {
      "beatId": "beat5",
      "source": "narration",
      "text": "But the check crosses the network.",
      "verdict": "supported",
      "ids": ["fact-8"],
      "restates": {
        "claim": "the limiter check costs a network round trip",
        "fact": "keeping the bucket in one shared store costs a network round trip on every request"
      }
    },
    {
      "beatId": "beat5",
      "source": "narration",
      "text": "What if the store gets slow?",
      "verdict": "no_claim",
      "ids": []
    },
    {
      "beatId": "beat5",
      "source": "narration",
      "text": "Say the median round trip is zero point four milliseconds.",
      "verdict": "supported",
      "ids": ["fact-8", "num-5"],
      "restates": {
        "claim": "the median round trip is 0.4 ms",
        "fact": "the round trip is 0.4 ms at the median"
      }
    },
    {
      "beatId": "beat5",
      "source": "narration",
      "text": "At p ninety-nine, two point one.",
      "verdict": "supported",
      "ids": ["fact-8", "num-6"],
      "restates": {
        "claim": "the p99 round trip is 2.1 ms",
        "fact": "the round trip is 2.1 ms at p99"
      }
    },
    {
      "beatId": "beat5",
      "source": "value",
      "elementId": "latency",
      "text": "0.4",
      "label": "round trip per request",
      "verdict": "supported",
      "ids": ["num-5"],
      "restates": {
        "claim": "the round trip is 0.4 ms at the median",
        "fact": "median network round trip is 0.4 ms"
      }
    },
    {
      "beatId": "beat5",
      "source": "value",
      "elementId": "latency",
      "text": "2.1",
      "label": "round trip per request",
      "verdict": "issue",
      "ids": []
    },
    {
      "beatId": "beat6",
      "source": "narration",
      "text": "Then a routine failover moved that store to a replica in another zone.",
      "verdict": "supported",
      "ids": ["fact-19"],
      "restates": {
        "claim": "a failover moved the store to a replica in another zone",
        "fact": "a routine failover moved the limiter's store to a replica in another zone"
      }
    },
    {
      "beatId": "beat6",
      "source": "narration",
      "text": "Store calls went from one millisecond to eighty milliseconds.",
      "verdict": "supported",
      "ids": ["fact-19", "num-16", "num-17"],
      "restates": {
        "claim": "store calls went from 1 ms to 80 ms",
        "fact": "store calls went from about 1 ms to 80 ms"
      }
    },
    {
      "beatId": "beat6",
      "source": "narration",
      "text": "Those calls blew past the timeout, so every check counted as a failure.",
      "verdict": "supported",
      "ids": ["fact-20", "fact-19"],
      "restates": {
        "claim": "calls over the timeout counted as failures",
        "fact": "calls over the store timeout counted as failures"
      }
    },
    {
      "beatId": "beat6",
      "source": "value",
      "elementId": "latency_card",
      "text": "80",
      "label": "Store call after failover",
      "verdict": "supported",
      "ids": ["num-16"],
      "restates": {
        "claim": "the store call after failover is 80 ms",
        "fact": "store call latency after the failover was 80 ms"
      }
    },
    {
      "beatId": "beat7",
      "source": "narration",
      "text": "So with the store slow, the limiter let requests through uncounted.",
      "verdict": "supported",
      "ids": ["fact-20"],
      "restates": {
        "claim": "the limiter let requests through uncounted",
        "fact": "the limiter was configured to fail open, so each instance enforced the limit locally"
      }
    },
    {
      "beatId": "beat7",
      "source": "narration",
      "text": "Each of the forty checkout instances enforced the limit alone.",
      "verdict": "supported",
      "ids": ["fact-20", "num-18"],
      "restates": {
        "claim": "40 checkout instances each enforced the limit locally",
        "fact": "each of the 40 checkout instances enforced the limit locally"
      }
    },
    {
      "beatId": "beat7",
      "source": "narration",
      "text": "Traffic reached the payment provider at roughly forty times its contracted rate.",
      "verdict": "supported",
      "ids": ["fact-20", "num-19"],
      "restates": {
        "claim": "traffic to the provider reached roughly 40 times its contracted rate",
        "fact": "traffic to the payment provider reached roughly 40 times its contracted rate of 300 requests per second"
      }
    },
    {
      "beatId": "beat7",
      "source": "narration",
      "text": "Checkouts started failing.",
      "verdict": "supported",
      "ids": ["fact-21", "num-15"],
      "restates": {
        "claim": "checkout requests began to fail",
        "fact": "checkout errors rose to 31% as the provider answered 429"
      }
    },
    {
      "beatId": "beat7",
      "source": "value",
      "elementId": "inst_a",
      "text": "1",
      "label": "title \"CHECKOUT 1\"",
      "verdict": "no_claim",
      "ids": []
    },
    {
      "beatId": "beat7",
      "source": "value",
      "elementId": "inst_b",
      "text": "2",
      "label": "title \"CHECKOUT 2\"",
      "verdict": "no_claim",
      "ids": []
    },
    {
      "beatId": "beat8",
      "source": "narration",
      "text": "The payment limiter now refuses what it can't count.",
      "verdict": "supported",
      "ids": ["fact-23"],
      "restates": {
        "claim": "the payment limiter fails closed",
        "fact": "after the incident the payment-provider limiter fails closed"
      }
    },
    {
      "beatId": "beat8",
      "source": "narration",
      "text": "If the store fails, each instance gets its share of the contract.",
      "verdict": "supported",
      "ids": ["fact-23"],
      "restates": {
        "claim": "each instance enforces a share of the limit",
        "fact": "local fallback limits are divided by the number of instances so together they stay within the contracted rate"
      }
    },
    {
      "beatId": "beat8",
      "source": "narration",
      "text": "The timeout rose to a hundred and fifty milliseconds, longer than a cross-zone trip.",
      "verdict": "supported",
      "ids": ["fact-23", "num-20"],
      "restates": {
        "claim": "the store timeout rose to 150 ms, above a cross-zone round trip",
        "fact": "the store timeout rose to 150 ms, above a cross-zone round trip"
      }
    },
    {
      "beatId": "beat8",
      "source": "narration",
      "text": "So that checkout waits, or is refused.",
      "verdict": "supported",
      "ids": ["fact-23"],
      "restates": {
        "claim": "a checkout request now waits longer or is refused",
        "fact": "the limiter fails closed on uncounted traffic and the longer timeout makes slow-store requests wait before being decided"
      }
    },
    {
      "beatId": "beat8",
      "source": "value",
      "elementId": "store-timeout",
      "text": "150",
      "label": "Store timeout after fix",
      "verdict": "supported",
      "ids": ["num-20"],
      "restates": {
        "claim": "the store timeout after the fix is 150 ms",
        "fact": "store timeout for the checkout limiter after the incident is 150 ms"
      }
    }
  ],
  "issues": [
    {
      "beatId": "beat2",
      "category": "unsupported_claim",
      "severity": "blocking",
      "owner": "generator",
      "fields": ["board"],
      "evidence": [
        {
          "kind": "label",
          "elementId": "bucket",
          "quote": "capacity"
        },
        {
          "kind": "narration",
          "quote": "Say the bucket holds a hundred tokens."
        },
        {
          "kind": "number",
          "id": "num-1"
        },
        {
          "kind": "fact",
          "id": "fact-1",
          "quote": "capacity and refill rate"
        }
      ],
      "problem": "The bucket counter is labelled \"capacity\" and counts down 100 to 99 on the spend, so the board claims the capacity drops to 99 tokens; the notes give a fixed capacity of 100 and only the token count falls when a token is spent.",
      "fix": "Relabel the counter \"tokens\" (the token count) and leave capacity as the fixed 100 from num-1."
    },
    {
      "beatId": "beat5",
      "category": "number_wrong_meaning",
      "severity": "blocking",
      "owner": "generator",
      "fields": ["board"],
      "evidence": [
        {
          "kind": "label",
          "elementId": "latency",
          "quote": "round trip per request"
        },
        {
          "kind": "narration",
          "quote": "At p ninety-nine, two point one."
        },
        {
          "kind": "number",
          "id": "num-6"
        },
        {
          "kind": "fact",
          "id": "fact-8",
          "quote": "0.4 ms at the median and 2.1 ms at p99"
        }
      ],
      "problem": "The single counter runs 0.4 to 2.1 under one label and changes from neutral to problem, drawing the median and the p99 of the same measurements as one round trip getting slower, while num-6's 2.1 ms is a percentile of the same measurements, not a later value.",
      "fix": "Show the two figures as two separate readings labelled median and p99 instead of animating one counter upward."
    }
  ]
}

